BEGIN;
CREATE TABLE IF NOT EXISTS vault_workspace_members(workspace_id uuid NOT NULL REFERENCES vault_workspaces(id) ON DELETE CASCADE,user_id uuid NOT NULL,role text NOT NULL CHECK(role IN('OWNER','ADMIN','MEMBER','AUDITOR')),status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','INVITED','DISABLED')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS vault_plans(code text PRIMARY KEY,kind text NOT NULL CHECK(kind IN('CONSUMER','BUSINESS')),quota_bytes bigint NOT NULL,monthly_price_minor integer NOT NULL,currency char(3) NOT NULL DEFAULT 'USD',features jsonb NOT NULL DEFAULT '{}',active boolean NOT NULL DEFAULT true);
INSERT INTO vault_plans(code,kind,quota_bytes,monthly_price_minor) VALUES('FREE_5GB','CONSUMER',5368709120,0),('C25','CONSUMER',26843545600,199),('C40','CONSUMER',42949672960,299),('C60','CONSUMER',64424509440,399),('C1TB','CONSUMER',1099511627776,1499) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS vault_policy_profiles(workspace_id uuid PRIMARY KEY REFERENCES vault_workspaces(id) ON DELETE CASCADE,export_social text NOT NULL DEFAULT 'ALLOW_STEP_UP' CHECK(export_social IN('ALLOW','ALLOW_STEP_UP','DENY')),external_links text NOT NULL DEFAULT 'ALLOW_STEP_UP' CHECK(external_links IN('ALLOW','ALLOW_STEP_UP','DENY')),retention_days integer,dlp_mode text NOT NULL DEFAULT 'STANDARD' CHECK(dlp_mode IN('STANDARD','STRICT')),updated_at timestamptz NOT NULL DEFAULT now());
COMMIT;
